#include "trajectory.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
namespace fs=std::filesystem;
Json read(fs::path p){std::ifstream f(p);if(!f)throw std::runtime_error(p.string());Json j;f>>j;return j;}
Vector deriv(const Curve&c,double u,int d,double T){Vector v=Vector::Zero();for(int k=7;k>=d;--k){double a=1;for(int j=0;j<d;++j)a*=k-j;v=u*v+a*c.row(k).transpose();}return v/std::pow(T,d);}
int main(int argc,char**argv){try{fs::path p=argv[1],e=p.parent_path();auto rows=read(p/(argc>2?argv[2]:"results")/"SUMMARY.json");Json counts=Json::object(),failures=Json::object();double max_join=0,max_center=0,max_obj=0;int candidates=0,converged=0,trial_errors=0,choices=0;for(auto&r:rows){std::string v=r["verdict"];counts[v]=counts.value(v,0)+1;auto raw=read(r["result"].get<std::string>());std::string lv=r["level"];auto scene=read(e/"robust_ipopt_full_20261117/source_inputs/assets"/lv/"scene.json");if(!raw["failure"].is_null()){std::string f=raw["failure"];failures[f]=failures.value(f,0)+1;}if(!raw["durations"].empty()){auto tr=Trajectory::load(raw);for(size_t i=1;i<tr.durations.size();++i)for(int d=0;d<4;++d){auto a=deriv(tr.coefficients[i-1],1.,d,tr.durations[i-1]),b=deriv(tr.coefficients[i],0.,d,tr.durations[i]);max_join=std::max(max_join,(a-b).norm()/(1.+a.norm()+b.norm()));}}for(auto&q:raw["requests"]){int gate=q["gate"].get<int>()-1;auto w=load_window(scene["windows"][gate]);double best=INFINITY;int best_index=-1,k=0;for(auto&c:q["candidates"]){++candidates;auto&s=c["stats"];converged+=s["eligible"].get<bool>();trial_errors+=s.value("trial_evaluation_error",false);if(!s["objective_consistency_error"].is_null())max_obj=std::max(max_obj,s["objective_consistency_error"].get<double>());if(s["eligible"].get<bool>()){Trajectory t;t.start=q["race_time_s"];for(auto&d:c["durations"])for(int j=0;j<4;++j)t.durations.push_back(d.get<double>()/4.);for(auto&cc:c["coefficients"]){Curve co;for(int power=0;power<8;++power)for(int axis=0;axis<3;++axis)co(power,axis)=cc[power][axis];t.coefficients.push_back(co);}double at=t.start+c["durations"][0].get<double>();max_center=std::max(max_center,(t.sample(at)-w.center-w.rotation*w.motion(at)).norm());if(c["task_event"]["passed"].get<bool>()&&s["objective_scaled"].get<double>()<best){best=s["objective_scaled"];best_index=k;}}++k;}if(!q["selected_seed"].is_null()){if(best_index!=q["selected_seed"].get<int>())throw std::runtime_error("Selection mismatch");++choices;}else if(best_index>=0)throw std::runtime_error("Usable candidate discarded");}}
Json audit={{"complete",rows.size()==22},{"counts",counts},{"failure_reasons",failures},{"candidate_count",candidates},{"eligible_count",converged},{"trial_evaluation_errors",trial_errors},{"selected_candidates",choices},{"maximum_C3_join_relative_error",max_join},{"maximum_dynamic_center_error_m",max_center},{"maximum_returned_objective_error",max_obj}};audit["passed"]=max_join<1e-7&&max_center<1e-7&&max_obj<1e-6&&rows.size()==22;std::ofstream(p/"FINAL_AUDIT.json")<<audit.dump(2)<<'\n';std::cout<<audit.dump(2)<<'\n';
auto own=read(e/"robust_ipopt_full_20261117/results/SUMMARY.json"),togt=read(e/"dynamic_togt_audit_20261117/results/SUMMARY.json");std::ofstream o(p/"FIVE_METHODS.md");o<<"# 同场景五方法规划结果\n\n单位秒。不同方法按各自冻结实现求解，不是同预算同目标的消融。本文八配置权重1000；TOGT作者单初值权重1；Wang局部N2/M4、四时间初值、论文TableIII罚权及已注明的任务适配。未实飞；通过仅指共同名义碰撞、门序、终点的数值复查。碰撞时间不计有效成绩，Wang未到终点的前缀不是完整竞速时间。\n\n|条件|本文自由|本文中心|TOGT自由|TOGT中心|Wang|\n|---|---:|---:|---|---|---|\n"<<std::fixed<<std::setprecision(3);for(auto&r:own){std::string lv=r["level"];o<<"|"<<lv<<"|"<<r["methods"]["ours"]["nominal_time_s"].get<double>()<<"|"<<r["methods"]["center"]["nominal_time_s"].get<double>();for(std::string m:{"free","center"})for(auto&t:togt)if(t["level"]==lv&&t["mode"]==m){o<<"|";if(t["verdict"]!="通过")o<<t["verdict"].get<std::string>()<<"（";o<<t["trajectory_s"].get<double>();if(t["verdict"]!="通过")o<<"）";}for(auto&w:rows)if(w["level"]==lv){o<<"|";if(w["verdict"]!="通过")o<<w["verdict"].get<std::string>();if(!w["trajectory_s"].is_null()){if(w["verdict"]!="通过")o<<"（";o<<w["trajectory_s"].get<double>();if(w["verdict"]!="通过")o<<"）";}else o<<"（未到终点）";}o<<"|\n";}
return audit["passed"].get<bool>()?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
